<script>
    $('.icon_plus_minus').on('click', function() {
        if ($(this).hasClass('bi-dash')) {
            $(this).removeClass('bi-dash').addClass('bi-plus').css('color', 'black');
        } else {
            $('.icon_plus_minus').removeClass('bi-dash').addClass('bi-plus').css('color', 'black');
            $(this).removeClass('bi-plus').addClass('bi-dash').css('color', 'red');
        }
    });
</script>